<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function ea_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())ea_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))ea_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);$uid=(int)$_SESSION['user_id'];$role=(string)$_SESSION['role'];$staffRoles=['admin','director','sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'];if(!in_array($role,$staffRoles,true))ea_json(403,['ok'=>false,'message'=>'Only linked school staff can use staff attendance.']);$school=filter_var($_REQUEST['school_id']??null,FILTER_VALIDATE_INT);if(!$school)ea_json(422,['ok'=>false,'message'=>'Choose a school.']);$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())ea_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$leaders=['admin','director','sub_director','headteacher','hr'];$canReport=in_array($role,$leaders,true);$today=date('Y-m-d');
if($_SERVER['REQUEST_METHOD']==='GET'){$date=(string)($_GET['date']??$today);if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4)))ea_json(422,['ok'=>false,'message'=>'Choose a valid attendance date.']);$q=$db->prepare('SELECT id,attendance_date,check_in_at,check_out_at FROM employee_attendance WHERE school_id=? AND user_id=? AND attendance_date=?');$q->execute([$school,$uid,$today]);$mine=$q->fetch()?:null;$rows=[];if($canReport){$rolesSql="'admin','director','sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'";$q=$db->prepare("SELECT u.id user_id,u.name,u.role,a.id,a.check_in_at,a.check_out_at FROM school_memberships m JOIN users u ON u.id=m.user_id LEFT JOIN employee_attendance a ON a.school_id=m.school_id AND a.user_id=u.id AND a.attendance_date=? WHERE m.school_id=? AND u.role IN ($rolesSql) ORDER BY u.name");$q->execute([$date,$school]);$rows=$q->fetchAll();}ea_json(200,['ok'=>true,'data'=>['today'=>$today,'mine'=>$mine,'date'=>$date,'can_report'=>$canReport,'rows'=>$rows]]);}
if($_SERVER['REQUEST_METHOD']!=='POST')ea_json(405,['ok'=>false,'message'=>'Method not allowed.']);verify_csrf();$action=(string)($_POST['action']??'');if(!in_array($action,['check_in','check_out'],true))ea_json(422,['ok'=>false,'message'=>'Choose check in or check out.']);$now=date('Y-m-d H:i:s');try{$db->beginTransaction();if($action==='check_in'){$q=$db->prepare('INSERT INTO employee_attendance(school_id,user_id,attendance_date,check_in_at,check_in_by) VALUES(?,?,?,?,?)');$q->execute([$school,$uid,$today,$now,$uid]);$id=(int)$db->lastInsertId();$auditAction='check_in';}else{$q=$db->prepare('SELECT id,check_in_at,check_out_at FROM employee_attendance WHERE school_id=? AND user_id=? AND attendance_date=? FOR UPDATE');$q->execute([$school,$uid,$today]);$entry=$q->fetch();if(!$entry||$entry['check_out_at'])throw new DomainException('You need an open check-in for today before checking out.');if($now<$entry['check_in_at'])throw new DomainException('Check-out time cannot be earlier than check-in.');$q=$db->prepare('UPDATE employee_attendance SET check_out_at=?,check_out_by=? WHERE id=? AND school_id=? AND check_out_at IS NULL');$q->execute([$now,$uid,$entry['id'],$school]);if($q->rowCount()!==1)throw new DomainException('This attendance entry was already closed.');$id=(int)$entry['id'];$auditAction='check_out';}$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$uid,$auditAction,'employee_attendance',$id,json_encode(['school_id'=>$school,'attendance_date'=>$today,'recorded_at'=>$now],JSON_THROW_ON_ERROR)]);if($db->inTransaction())$db->commit();ea_json(200,['ok'=>true,'message'=>$action==='check_in'?'Check-in recorded.':'Check-out recorded.']);}catch(DomainException $e){if($db->inTransaction())$db->rollBack();ea_json(409,['ok'=>false,'message'=>$e->getMessage()]);}catch(PDOException $e){if($db->inTransaction())$db->rollBack();if($e->getCode()==='23000')ea_json(409,['ok'=>false,'message'=>'You already checked in today.']);error_log('Employee attendance failed: '.$e->getMessage());ea_json(500,['ok'=>false,'message'=>'Staff attendance could not be saved.']);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Employee attendance failed: '.$e->getMessage());ea_json(500,['ok'=>false,'message'=>'Staff attendance could not be saved.']);}